"""Own inspection of the delivery against QA-W100 (an approximation of the rig).
python3 check.py [movement.json|variant_6h.json] [--quick] [--print] [--asm]"""
import json
import math
import os
import sys
import time
from fractions import Fraction as Fr

import numpy as np
import manifold3d as m3

HERE = os.path.dirname(os.path.abspath(__file__))
APP = os.path.abspath(os.path.join(HERE, "..", ".."))
sys.path.insert(0, os.path.join(APP, "tools"))
sys.path.insert(0, HERE)
import kernel  # noqa: E402
import qa  # noqa: E402

DEL = os.path.join(APP, "delivery")
CACHE = os.environ.get("PARTCACHE", "/tmp/claude-0/-tmp-claude-0-runs-thin1-opus-app/7c764678-0ff0-4c8a-b9ba-a7a4eee3d0db/scratchpad/cache")
os.makedirs(CACHE, exist_ok=True)

LEWIS = {}


def lewis(z):
    if not LEWIS:
        txt = open(os.path.join(APP, "datasheets", "DS-W04_gear_rating.md")).read()
        sec = txt.split("## 3.")[1]
        for line in sec.splitlines():
            c = [x.strip() for x in line.strip().strip("|").split("|")]
            if len(c) == 11 and c[0].isdigit():
                for u in range(10):
                    if c[u + 1] not in ("–", "-"):
                        LEWIS[int(c[0]) + u] = float(c[u + 1])
    return LEWIS[z]


def load(name):
    p = os.path.join(DEL, "parts", name + ".step")
    cp = os.path.join(CACHE, name + ".stl")
    if os.path.exists(cp) and os.path.getmtime(cp) > os.path.getmtime(p):
        return kernel.tris_to_part(kernel.read_stl(cp, 10 ** 7, 10 ** 9), 0.005)
    man = kernel.load_step_part(p, 16777216, 200000, 0.001, 0.1, 500, 120, 4096, 0.005)
    kernel.write_stl(cp, man)
    return man


def barrel():
    return kernel.tris_to_manifold(kernel.read_stl(os.path.join(APP, "supplied", "barrel.stl"), 10 ** 7, 10 ** 9))


def rot(man, axis, a):
    return qa.rot_about(man, axis, a)


def main(fname, quick=False, do_print=False, do_asm=False):
    doc = json.load(open(os.path.join(DEL, fname)))
    period = Fr(8) if fname == "movement.json" else Fr(6)
    nB = Fr(-1) / period         # turns per hour, CCW positive: barrel clockwise
    res = {}
    t0 = time.time()
    fixed = {n: load(n) for n in doc["fixed"]}
    mob = {"barrel": {"axis": (0.0, 0.0), "parts": {"barrel": barrel()}}}
    for k, m in doc["mobiles"].items():
        mob[k] = {"axis": tuple(m["axis"]), "parts": {n: load(n) for n in m["parts"]}}
    for k in mob:
        mob[k]["solid"] = kernel.union(list(mob[k]["parts"].values()))
    frame = kernel.union(list(fixed.values()))
    print("loaded in %.0f s" % (time.time() - t0))

    # C2
    bad = []
    names = list(mob)
    for i, a in enumerate(names):
        v = kernel.ivol(frame, mob[a]["solid"])
        if v > 0.01:
            bad.append(("frame", a, v))
        for b in names[i + 1:]:
            v = kernel.ivol(mob[a]["solid"], mob[b]["solid"])
            if v > 0.01:
                bad.append((a, b, v))
        ps = list(mob[a]["parts"].items())
        for x in range(len(ps)):
            for y in range(x + 1, len(ps)):
                v = kernel.ivol(ps[x][1], ps[y][1])
                if v > 0.01:
                    bad.append((ps[x][0], ps[y][0], v))
    fl = list(fixed.items())
    for x in range(len(fl)):
        for y in range(x + 1, len(fl)):
            v = kernel.ivol(fl[x][1], fl[y][1])
            if v > 0.01:
                bad.append((fl[x][0], fl[y][0], v))
    # frame link (chain)
    if len(fl) > 1:
        linked = {fl[0][0]}
        changed = True
        while changed:
            changed = False
            for n, s in fl:
                if n in linked:
                    continue
                if any(kernel.min_distance(s, fixed[l], 0.05) <= 0.01 for l in linked):
                    linked.add(n)
                    changed = True
        if len(linked) != len(fl):
            bad.append(("frame not linked", linked))
    res["C2"] = bad
    print("C2", bad or "ok")

    # 1 free to turn
    bad = []
    nang = 36 if quick else 120
    for a in names:
        s, ax = mob[a]["solid"], mob[a]["axis"]
        worst = 0
        for i in range(nang):
            v = kernel.ivol(frame, rot(s, ax, 2 * math.pi * i / nang))
            worst = max(worst, v)
        if worst > 0.01:
            bad.append((a, worst))
    res["1"] = bad
    print("1 free", bad or "ok")

    # 2 held
    dirs = {"+x": (1, 0, 0), "-x": (-1, 0, 0), "+y": (0, 1, 0), "-y": (0, -1, 0), "+z": (0, 0, 1), "-z": (0, 0, -1)}
    held = {a: {} for a in names}
    for a in names:
        for dn, d in dirs.items():
            s = mob[a]["solid"].translate([0.3 * d[0], 0.3 * d[1], 0.3 * d[2]])
            held[a][dn] = kernel.ivol(s, frame) > 0.01
    # coaxial help
    for _ in range(3):
        for a in names:
            for dn, d in dirs.items():
                if held[a][dn]:
                    continue
                s = mob[a]["solid"].translate([0.3 * d[0], 0.3 * d[1], 0.3 * d[2]])
                for b in names:
                    if b != a and math.dist(mob[a]["axis"], mob[b]["axis"]) <= 0.01 and held[b][dn]:
                        if kernel.ivol(s, mob[b]["solid"]) > 0.01:
                            held[a][dn] = True
    bad = [(a, dn) for a in names for dn in dirs if not held[a][dn]]
    res["2"] = bad
    print("2 held", bad or "ok")

    # 3 seated
    bad = []
    for a in names:
        ps = mob[a]["parts"]
